                        currEntities.Add(myentity);
                    }
                    if (myfield != null && myentity != null)
                        AddToSelect(ref select, ref where, ref groupby, ref having, parameters, field, myfield, myentity);

                }

                if (currEntities.Count > 1)
                {
                    from = CreateJoinString(fields, from, currEntities);
                }
                else
                {
                    Entities myentity = currEntities[0];
                    from += "[dbo].[" + myentity.SysName + "] as [" + myentity.DisplayName + "] ";
                }
                if (select != "")
                {
                    select = "SELECT " + select;
                }
                if (from != "")
                {
