                }
                if (where != "")
                {
                    where = " WHERE " + where;
                }
                if (groupby != "")
                {
                    groupby = " GROUP BY " + groupby;
                    if(having!="")
                    {
                        having = " HAVING " + having;
                    }
                }
                if (select != "" && from != "")
                {
